export enum TrackingEvents {
  TRACKING_LOADED = "trackingConsentLoaded",
  TRACKING_ACCEPTED = "trackingConsentAccepted",
  TRACKING_DECLINED = "trackingConsentDeclined",
  TRACKING_RESET = "trackingConsentReset",
}

export enum ConsentValuesV1 {
  ACCEPTED = "yes",
  DECLINED = "no",
  NO_INTERACTION = "no_interaction",
  NO_VALUE = "",
}

export enum ConsentValuesV2 {
  NO_INTERACTION = "no_interaction",
  NO_VALUE = "",
  ACCEPTED = "1",
  DECLINED = "0",
}

export enum TrackingRegulations {
  GDPR = "GDPR",
  CCPA = "CCPA",
  NO_VALUE = "",
}

export enum TrackingRegulationLimitations {
  CCPA_BLOCK_ALL = "CCPA_BLOCK_ALL",
  GDPR = "GDPR",
}

export type V1_1SchemaCookie = {
  consent: ConsentValuesV1;
  regulation: TrackingRegulations;
  version: string;
  prefs: {
    limit: TrackingRegulationLimitations[];
  };
}

export const v1_1SchemaKeys = ["prefs", "version", "consent", "regulation"];

export type V2_0SchemaCookie = {
  v: string;
  reg: TrackingRegulations;
  lim: TrackingRegulationLimitations[];
  con: {
    GDPR?: ConsentValuesV2;
  };
}

export const v2_0SchemaKeys = ["lim", "v", "con", "reg"];

export type ConsentCookie = V2_0SchemaCookie | V1_1SchemaCookie;

export type ShopPrefs = {
  limit: TrackingRegulationLimitations[];
};

export type ConsentAPIResponse = {
  userCanBeTracked: boolean | Error;
  userTrackingConsent: ConsentValuesV1;
};

export interface RegulationLimitDictionary {
  GDPR: TrackingRegulationLimitations[],
  CCPA: TrackingRegulationLimitations[],
}

export function eventFactory(eventName, payload = {}) {
  try {
    return new CustomEvent(eventName, {
      detail: payload,
    });
  } catch (err) {
    return new Error(err);
  }
}

export function areArraysEqual(array1: string[], array2: string[]): boolean {
  const sortedArray2 = array2.slice().sort();
  return (
    array1.length === array2.length &&
    array1
      .slice()
      .sort()
      .every((value, index) => value === sortedArray2[index])
  );
}

export function isArrayEmpty(array: string[]): boolean {
  return array.length === 0;
}

import {
  ConsentCookie,
  ConsentValuesV1,
  ConsentValuesV2,
  TrackingRegulations,
  ShopPrefs,
  TrackingRegulationLimitations,
  V1_1SchemaCookie,
  V2_0SchemaCookie,
  v1_1SchemaKeys,
  v2_0SchemaKeys
} from "./types";

import { areArraysEqual } from "./utils";

export const CONSENT_COOKIE_NAME = "_tracking_consent";

function readCookie(): V2_0SchemaCookie | undefined {
  try {
    const cookies = document.cookie ? document.cookie.split("; ") : [];
    let result = undefined;
    cookies.forEach((cookie) => {
      const [name, value] = cookie.split("=");

      if (CONSENT_COOKIE_NAME === decodeURIComponent(name)) {
        var cookieObj = JSON.parse(decodeURIComponent(value));

        result = cookieObj;
      }
    });

    if (result === undefined || cookieMalformed(result)) {
      return undefined;
    }

    if (usingV1_1CookieSchema(result)) {
      result = transformCookieToNewSchema(result);
    }

    return result;
  } catch {
    return undefined;
  }
}

export function getRegulationValue(): TrackingRegulations {
  const cookie = readCookie();

  if (validCookieDoesNotExist(cookie)) {
    return TrackingRegulations.NO_VALUE;
  }

  return cookie.reg;
}

