      xhr.status === 0 || (200 >= xhr.status && xhr.status < 400);
    let responseJson;

    try {
      responseJson = JSON.parse(xhr.responseText);
    } catch (err) {
      responseJson = {
        error: "Unknown error",
      };
    }

    if (statusOk) {
      if (customEvent) {
        document.dispatchEvent(
          new CustomEvent(customEvent, {
            detail: {},
          })
